draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';
  ctx.fillStyle = 'black';

  // table
  ctx.fillRect(W/2-50, H/2+20, 100, 30);
  ctx.strokeRect(W/2-50, H/2+20, 100, 30);

  // journal
  ctx.fillRect(W/2-40, H/2+25, 80, 20);
  ctx.strokeRect(W/2-40, H/2+25, 80, 20);

  // pen
  ctx.beginPath();
  ctx.moveTo(W/2-30, H/2+45);
  ctx.lineTo(W/2-30, H/2+70);
  ctx.stroke();

  // person
  ctx.beginPath();
  ctx.arc(W/2, H/2-50, 20, 0, 2 * Math.PI);
  ctx.fill();
  ctx.stroke();

  // arm
  ctx.beginPath();
  ctx.moveTo(W/2, H/2-30);
  ctx.lineTo(W/2-30, H/2+50 + 20 * Math.sin(t));
  ctx.stroke();

  // hand
  ctx.beginPath();
  ctx.arc(W/2-30, H/2+50 + 20 * Math.sin(t), 10, 0, 2 * Math.PI);
  ctx.fill();
  ctx.stroke();

  ctx.restore();
}
